/* Specificity Battle Example */

/* Specificity: 0,0,1 (one tag) */
p { color: black; }

/* Specificity: 0,1,0 (one class) — WINS */
.intro { color: blue; }

/* Specificity: 1,0,0 (one ID) — WINS OVER BOTH */
#lead { color: red; }

/* Specificity: 0,1,1 (class + tag) */
p.highlight { color: green; }

/* Specificity: 1,0,1 (ID + tag) — WINS */
p#lead { color: purple; }

/* Reset box model for all elements */
*, *::before, *::after {
  box-sizing: border-box;
}

.card {
  width: 300px;
  padding: 20px;
  border: 3px solid #6366f1;
  margin: 15px auto;
  background-color: #ffffff;
}

/* Visualizing the layers */
.box-visual {
  background-color: #e0e7ff; /* Content bg */
  padding: 30px;             /* Inner space */
  border: 5px dashed #4338ca; /* Border */
  margin: 20px;              /* Outer space */
}

/* Decorative quote marks using ::before and ::after */
blockquote {
  position: relative;
  padding: 20px 40px;
  background: #f3f4f6;
  border-left: 4px solid #6366f1;
}

blockquote::before {
  content: "\201C"; /* Unicode left double quote */
  font-size: 4rem;
  color: #6366f1;
  position: absolute;
  top: -10px;
  left: 10px;
  opacity: 0.3;
}

blockquote::after {
  content: "\201D"; /* Unicode right double quote */
  font-size: 4rem;
  color: #6366f1;
  position: absolute;
  bottom: -30px;
  right: 10px;
  opacity: 0.3;
}

/* Tooltip arrow using ::after */
.tooltip {
  position: relative;
  background: #1f2937;
  color: white;
  padding: 8px 12px;
  border-radius: 4px;
}

.tooltip::after {
  content: "";
  position: absolute;
  top: 100%;
  left: 50%;
  transform: translateX(-50%);
  border-width: 6px;
  border-style: solid;
  border-color: #1f2937 transparent transparent transparent;
}

/* Mobile First: Base styles for small screens */
.container {
  padding: 1rem;
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

/* Tablet and up */
@media (min-width: 768px) {
  .container {
    flex-direction: row;
    flex-wrap: wrap;
  }
  .card {
    flex: 1 1 calc(50% - 1rem);
  }
}

/* Desktop and up */
@media (min-width: 1024px) {
  .container {
    max-width: 1200px;
    margin: 0 auto;
  }
  .card {
    flex: 1 1 calc(33.333% - 1rem);
  }
}

/* Hide sidebar on mobile */
.sidebar {
  display: none;
}
@media (min-width: 992px) {
  .sidebar {
    display: block;
    width: 280px;
  }
}

// JavaScript to log current viewport width (useful for debugging)
function logViewport() {
  console.log(`Width: ${window.innerWidth}px`);
  console.log(`Height: ${window.innerHeight}px`);
  console.log(`Device pixel ratio: ${window.devicePixelRatio}`);
}

