// Simulating an API call with a Promise
function fetchUserData(userId) {
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      if (userId <= 0) {
        reject(new Error("Invalid user ID"));
      } else {
        resolve({ id: userId, name: "Alice", email: "alice@example.com" });
      }
    }, 1000); // 1 second delay
  });
}

// Using async/await with error handling
async function displayUser(userId) {
  try {
    console.log("Loading user...");
    const user = await fetchUserData(userId);
    console.log(`User loaded: ${user.name} (${user.email})`);
    return user;
  } catch (error) {
    console.error(`Failed to load user: ${error.message}`);
    return null;
  }
}

// Run it
displayUser(1);   // Success after 1 second
displayUser(-1);  // Error after 1 second

const form = document.getElementById("signup-form");
const nameInput = document.getElementById("username");
const greeting = document.getElementById("greeting");

// Input event — fires on every keystroke
nameInput.addEventListener("input", (event) => {
  greeting.textContent = `Hello, ${event.target.value || "Guest"}!`;
});

// Form submit event
form.addEventListener("submit", (event) => {
  event.preventDefault(); // Stop page reload

  const username = nameInput.value.trim();
  if (username.length < 3) {
    alert("Username must be at least 3 characters.");
    return;
  }

  // Save to localStorage
  const userData = { username, theme: "dark", loginCount: 1 };
  localStorage.setItem("currentUser", JSON.stringify(userData));

  console.log("Saved user:", userData);
  form.reset();
});

// Load on page start
window.addEventListener("DOMContentLoaded", () => {
  const saved = localStorage.getItem("currentUser");
  if (saved) {
    const user = JSON.parse(saved);
    greeting.textContent = `Welcome back, ${user.username}!`;
    console.log("Restored from storage:", user);
  }
});

// Click event with delegation
const buttonContainer = document.querySelector(".button-group");
buttonContainer.addEventListener("click", (event) => {
  if (event.target.matches(".action-btn")) {
    console.log("Button clicked:", event.target.textContent);
    event.target.classList.toggle("active");
  }
});

